const j = $input.first().json;
const nombre = j['Nombre completo'] || '';
const email = j['Email'] || '';
const telefono = j['Teléfono'] || '';
const empresa = j['Empresa'] || '';
const mensaje = j['¿En qué podemos ayudarte?'] || '';
const t = mensaje.toLowerCase();

const reglas = [
  ['Reclamación', 'Alta', ['queja', 'reclam', 'insatisfech', 'mal servicio', 'decepcionad']],
  ['Soporte técnico', 'Media', ['problema', 'error', 'no funciona', 'fall', 'soporte', 'incidencia']],
  ['Presupuesto / Cotización', 'Media', ['presupuesto', 'cotiz', 'precio', 'cost', 'tarifa']],
];

let categoria = 'Información general';
let prioridad = 'Baja';
for (const [cat, pri, kws] of reglas) {
  if (kws.some((k) => t.includes(k))) { categoria = cat; prioridad = pri; break; }
}
if (['urgente', 'inmediat', 'cuanto antes', 'hoy mismo'].some((k) => t.includes(k))) prioridad = 'Alta';

const textos = {
  'Reclamación': ['lamentamos los inconvenientes', 'Sentimos la experiencia que nos cuentas. Un responsable te contactará en breve para resolverlo.'],
  'Soporte técnico': ['hemos recibido tu incidencia', `Nuestro equipo técnico ya está en ello y te contactará${telefono ? ' al ' + telefono : ''} lo antes posible.`],
  'Presupuesto / Cotización': ['tu presupuesto está en camino', `Recibimos tu solicitud${empresa ? ' para ' + empresa : ''}. Te enviaremos una propuesta en 24-48h.`],
  'Información general': ['gracias por contactarnos', 'Hemos recibido tu mensaje y te responderemos personalmente en breve.'],
};
const [asuntoBase, cuerpoBase] = textos[categoria];

return [{
  json: {
    nombre, email, telefono, empresa, mensaje, categoria, prioridad,
    fecha: new Date().toISOString(),
    emailAsunto: `${nombre}, ${asuntoBase}`,
    emailCuerpo: `Hola ${nombre},\n\n${cuerpoBase}\n\nUn saludo,\nEl equipo`,
  },
}];
